// MAP YOUR PROVIDER HERE. Every sending provider names these fields
// differently; this node is the single place that translates. The contract
// downstream is fixed:
//
//   email              recipient address the provider could not deliver to
//                      (or that complained)
//   fault              'hard_bounce' | 'soft_bounce' | 'complaint'
//   provider_reference provider's own message/bounce id — CrowdRelay
//                      deduplicates retries on it, so a stable id here is
//                      what keeps a retried webhook from being counted twice
//   occurred_at        RFC 3339 timestamp of the event, not of this call
//
// Examples for common providers (uncomment and adapt):
//
// Postmark:  Type ('HardBounce'|'SoftBounce'|'SpamComplaint'), Email,
//            MessageID, BouncedAt
// Mailgun:   event ('bounced'|'complained'), recipient, Message-Id header,
//            timestamp (unix seconds)
// SendGrid:  event ('bounce'|'spamreport'), email, sg_message_id, timestamp
const b = $input.first().json.body ?? $input.first().json;

// --- BEGIN provider mapping (Postmark shown as the default) --------------
const KIND = {
  HardBounce: 'hard_bounce',
  SoftBounce: 'soft_bounce',
  SpamComplaint: 'complaint',
  // Mailgun / SendGrid equivalents:
  bounced: 'soft_bounce',
  complained: 'complaint',
  spamreport: 'complaint'
};
const fault = KIND[b.Type || b.event];
if (!fault) return []; // transient events we do not track (e.g. Delivered)
const out = {
  contact_email: String(b.Email || b.recipient || '').trim().toLowerCase(),
  fault,
  provider_reference: String(b.MessageID || b['Message-Id'] || b.sg_message_id || ''),
  occurred_at: new Date(
    b.BouncedAt ? Date.parse(b.BouncedAt) : (b.timestamp ? b.timestamp * 1000 : Date.now())
  ).toISOString()
};
// --- END provider mapping ------------------------------------------------

if (!out.contact_email.includes('@')) return [];
if (!out.provider_reference) {
  // Without a reference a retried webhook would count twice; fall back to a
  // deterministic hash of the event so at least identical replays collapse.
  out.provider_reference = 'no-ref:' + JSON.stringify([out.contact_email, out.fault, out.occurred_at]);
}
return [{ json: out }];
